            if shape & _orientations(other_points):
                matches.append((min(r for r,c in points), min(c for r,c in points), points))
                break
    if not matches:
        return [row[:] for row in grid]
    _, _, target = min(matches, key=lambda item: (item[0], item[1]))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out


